CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('CUSTOMER','CONTRACTOR_OWNER','CONTRACTOR_MANAGER','TECHNICIAN','OPERATIONS_AGENT','DISPATCHER','SUPPORT_AGENT','QUOTE_REVIEWER','ADMIN','SUPER_ADMIN');
CREATE TYPE request_status AS ENUM ('DRAFT','SUBMITTED','QUALIFICATION_PENDING','QUALIFIED','SCHEDULING','SCHEDULED','CONTRACTOR_SEARCH','ASSIGNED','TECHNICIAN_EN_ROUTE','TECHNICIAN_ARRIVED','ASSESSMENT_IN_PROGRESS','QUOTE_PENDING','QUOTE_SUBMITTED','QUOTE_APPROVED','QUOTE_REJECTED','MATERIALS_PENDING','WORK_SCHEDULED','WORK_IN_PROGRESS','ON_HOLD','CHANGE_ORDER_PENDING','COMPLETION_PENDING','COMPLETED','CANCELLED','DISPUTED','CLOSED');
CREATE TYPE verification_status AS ENUM ('PENDING','VERIFIED','REJECTED','EXPIRED','SUSPENDED');
CREATE TYPE quote_status AS ENUM ('DRAFT','SUBMITTED','ACCEPTED','REJECTED','EXPIRED','SUPERSEDED');
CREATE TYPE payment_status AS ENUM ('PENDING','REQUIRES_ACTION','PAID','FAILED','REFUNDED','WAIVED');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, display_name text NOT NULL, mfa_required boolean NOT NULL DEFAULT false, session_version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE user_roles (user_id uuid NOT NULL REFERENCES users(id), role user_role NOT NULL, PRIMARY KEY(user_id, role));
CREATE TABLE verticals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, config jsonb NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE service_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vertical_id uuid NOT NULL REFERENCES verticals(id), slug text NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(vertical_id, slug));
CREATE TABLE issue_types (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id uuid NOT NULL REFERENCES service_categories(id), slug text NOT NULL, name text NOT NULL, equipment_fields jsonb NOT NULL DEFAULT '[]', active boolean NOT NULL DEFAULT true, UNIQUE(category_id, slug));
CREATE TABLE properties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES users(id), label text NOT NULL, address_line1 text NOT NULL, city text NOT NULL, region text NOT NULL, postal_code text NOT NULL, latitude numeric(9,6), longitude numeric(9,6), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE INDEX properties_customer_idx ON properties(customer_id) WHERE deleted_at IS NULL;
CREATE TABLE contractors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, status verification_status NOT NULL DEFAULT 'PENDING', rating_bps integer NOT NULL DEFAULT 0 CHECK(rating_bps BETWEEN 0 AND 500), completion_rate_bps integer NOT NULL DEFAULT 0 CHECK(completion_rate_bps BETWEEN 0 AND 10000), avg_response_minutes integer NOT NULL DEFAULT 1440, service_areas jsonb NOT NULL DEFAULT '[]', vertical_ids jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE technicians (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES users(id), contractor_id uuid NOT NULL REFERENCES contractors(id), display_name text NOT NULL, active boolean NOT NULL DEFAULT true, emergency_available boolean NOT NULL DEFAULT false, workload integer NOT NULL DEFAULT 0, latitude numeric(9,6), longitude numeric(9,6), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE credentials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contractor_id uuid REFERENCES contractors(id), technician_id uuid REFERENCES technicians(id), code text NOT NULL, geography text NOT NULL DEFAULT '*', status verification_status NOT NULL DEFAULT 'PENDING', expiry_date date, verified_at timestamptz, document_key text, created_at timestamptz NOT NULL DEFAULT now(), CHECK((contractor_id IS NULL) <> (technician_id IS NULL)));
CREATE INDEX credential_eligibility_idx ON credentials(contractor_id, technician_id, code, status, expiry_date);
CREATE TABLE availability_blocks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), technician_id uuid NOT NULL REFERENCES technicians(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, available boolean NOT NULL DEFAULT true, CHECK(ends_at > starts_at));
CREATE TABLE service_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES users(id), property_id uuid NOT NULL REFERENCES properties(id), vertical_id uuid NOT NULL REFERENCES verticals(id), category_id uuid NOT NULL REFERENCES service_categories(id), issue_type_id uuid NOT NULL REFERENCES issue_types(id), urgency text NOT NULL CHECK(urgency IN ('STANDARD','EMERGENCY')), status request_status NOT NULL DEFAULT 'DRAFT', description text NOT NULL, equipment jsonb NOT NULL DEFAULT '{}', preferred_starts_at timestamptz, preferred_ends_at timestamptz, attachment_keys jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX service_request_customer_idx ON service_requests(customer_id, created_at DESC);
CREATE INDEX service_request_status_idx ON service_requests(status, vertical_id, created_at DESC);
CREATE TABLE jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_request_id uuid NOT NULL UNIQUE REFERENCES service_requests(id), contractor_id uuid NOT NULL REFERENCES contractors(id), technician_id uuid NOT NULL REFERENCES technicians(id), status request_status NOT NULL, assigned_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id), version integer NOT NULL, status quote_status NOT NULL DEFAULT 'DRAFT', contractor_subtotal_cents bigint NOT NULL DEFAULT 0, platform_fee_cents bigint NOT NULL DEFAULT 0, discount_cents bigint NOT NULL DEFAULT 0, tax_cents bigint NOT NULL DEFAULT 0, customer_total_cents bigint NOT NULL DEFAULT 0, currency char(3) NOT NULL DEFAULT 'CAD', notes text, expires_at timestamptz NOT NULL, accepted_at timestamptz, accepted_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(job_id, version));
CREATE UNIQUE INDEX quotes_one_accepted ON quotes(job_id) WHERE status = 'ACCEPTED';
CREATE TABLE quote_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quote_id uuid NOT NULL REFERENCES quotes(id) ON DELETE CASCADE, type text NOT NULL, title text NOT NULL, description text, quantity integer NOT NULL CHECK(quantity > 0), unit_price_cents bigint NOT NULL CHECK(unit_price_cents >= 0), subtotal_cents bigint NOT NULL CHECK(subtotal_cents >= 0), material_metadata jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vertical_id uuid NOT NULL REFERENCES verticals(id), min_amount_cents bigint NOT NULL, max_amount_cents bigint, rule jsonb NOT NULL, active boolean NOT NULL DEFAULT true, CHECK(max_amount_cents IS NULL OR max_amount_cents >= min_amount_cents));
CREATE TABLE payment_schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quote_id uuid NOT NULL UNIQUE REFERENCES quotes(id), total_cents bigint NOT NULL, currency char(3) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_milestones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), schedule_id uuid NOT NULL REFERENCES payment_schedules(id), sequence integer NOT NULL, trigger_name text NOT NULL, amount_cents bigint NOT NULL CHECK(amount_cents >= 0), evidence_required boolean NOT NULL DEFAULT false, status payment_status NOT NULL DEFAULT 'PENDING', paid_at timestamptz, UNIQUE(schedule_id, sequence));
CREATE TABLE payment_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), milestone_id uuid NOT NULL REFERENCES payment_milestones(id), provider text NOT NULL, provider_reference text NOT NULL, idempotency_key text NOT NULL UNIQUE, amount_cents bigint NOT NULL, currency char(3) NOT NULL, status payment_status NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider, provider_reference));
CREATE TABLE service_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id), job_id uuid NOT NULL UNIQUE REFERENCES jobs(id), vertical_id uuid NOT NULL REFERENCES verticals(id), summary text NOT NULL, equipment jsonb NOT NULL DEFAULT '{}', completed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL UNIQUE REFERENCES jobs(id), customer_id uuid NOT NULL REFERENCES users(id), overall smallint NOT NULL CHECK(overall BETWEEN 1 AND 5), quality smallint CHECK(quality BETWEEN 1 AND 5), professionalism smallint CHECK(professionalism BETWEEN 1 AND 5), timeliness smallint CHECK(timeliness BETWEEN 1 AND 5), communication smallint CHECK(communication BETWEEN 1 AND 5), comment text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), actor_type text NOT NULL, action text NOT NULL, entity_type text NOT NULL, entity_id uuid NOT NULL, before_state jsonb, after_state jsonb, metadata jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_event_entity_idx ON audit_events(entity_type, entity_id, occurred_at DESC);
CREATE TABLE processed_webhooks (provider text NOT NULL, event_id text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(provider, event_id));
CREATE TABLE idempotency_keys (key text PRIMARY KEY, actor_id uuid NOT NULL REFERENCES users(id), request_hash text NOT NULL, response jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE risk_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text NOT NULL, customer_id uuid REFERENCES users(id), contractor_id uuid REFERENCES contractors(id), job_id uuid REFERENCES jobs(id), score integer NOT NULL DEFAULT 0, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, reviewed_by uuid REFERENCES users(id));
